<section class="admin-header"><div><p class="eyebrow">Catalogo</p><h1><?= htmlspecialchars($title, ENT_QUOTES, 'UTF-8') ?></h1></div><a href="/SS_NOVA_TECHNOLOGY/public/admin/products">Volver</a></section>
<?php if (!empty($errors)): ?><div class="form-error" role="alert"><?php foreach ($errors as $error): ?><p><?= htmlspecialchars($error, ENT_QUOTES, 'UTF-8') ?></p><?php endforeach; ?></div><?php endif; ?>
<form class="admin-form" method="post" enctype="multipart/form-data" action="/SS_NOVA_TECHNOLOGY/public/admin/products/save"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrfToken, ENT_QUOTES, 'UTF-8') ?>"><?php if ($product): ?><input type="hidden" name="id" value="<?= (int) $product['id'] ?>"><input type="hidden" name="current_image_path" value="<?= htmlspecialchars($product['image_path'] ?? '', ENT_QUOTES, 'UTF-8') ?>"><?php endif; ?>
<label>Nombre<input name="name" required maxlength="180" value="<?= htmlspecialchars($product['name'] ?? '', ENT_QUOTES, 'UTF-8') ?>"></label>
<label>Categoria<select name="category_id" required><?php foreach ($categories as $category): ?><option value="<?= (int) $category['id'] ?>" <?= (int) ($product['category_id'] ?? 0) === (int) $category['id'] ? 'selected' : '' ?>><?= htmlspecialchars($category['name'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></label>
<label>Precio<input type="number" name="price" min="0" step="0.01" required value="<?= htmlspecialchars((string) ($product['price'] ?? '0'), ENT_QUOTES, 'UTF-8') ?>"></label><label>Stock<input type="number" name="stock" min="0" required value="<?= (int) ($product['stock'] ?? 0) ?>"></label>
<label>Imagen del producto<input type="file" name="product_image" accept="image/jpeg,image/png,image/webp,image/gif"><small class="form-help">Selecciona una imagen JPG, PNG, WEBP o GIF de máximo 5 MB. <?= !empty($product['image_path']) ? 'Si no eliges otra, se conserva la actual.' : '' ?></small></label>
<label>Descripcion<textarea name="description" rows="4"><?= htmlspecialchars($product['description'] ?? '', ENT_QUOTES, 'UTF-8') ?></textarea></label><label><input type="checkbox" name="is_active" <?= !isset($product['is_active']) || $product['is_active'] ? 'checked' : '' ?>> Producto activo</label><button class="button" type="submit">Guardar producto</button></form>